const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shuffle=arr=>{const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const fresh=()=>({version:1,lessons:[],vocabulary:{correct:0,total:0},grammar:{correct:0,total:0},quizzes:[],best:null});
let storageAvailable=true;
function readStorage(key){let raw;try{raw=localStorage.getItem(key)}catch{storageAvailable=false;return null}try{return JSON.parse(raw)}catch{return null}}
function saveStorage(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{storageAvailable=false;return false}}
function validateProgress(p){return p&&p.version===1&&Array.isArray(p.lessons)&&p.lessons.every(x=>typeof x==='string')&&['vocabulary','grammar'].every(k=>p[k]&&Number.isFinite(p[k].total)&&Number.isFinite(p[k].correct)&&p[k].total>=p[k].correct&&p[k].correct>=0)&&Array.isArray(p.quizzes)&&p.quizzes.every(q=>q&&typeof q.id==='string'&&typeof q.title==='string'&&Number.isFinite(q.score)&&Number.isFinite(q.total))&&(p.best===null||Number.isFinite(p.best))}
let progress=readStorage('bus201.progress.v1');if(!validateProgress(progress))progress=fresh();
let session=readStorage('bus201.session.v1');
function validSession(s){return s&&typeof s.id==='string'&&Array.isArray(s.questions)&&s.questions.length>0&&s.questions.every(q=>q&&BANK.some(b=>b.id===q.id))&&s.answers&&typeof s.answers==='object'&&Number.isInteger(s.index)&&s.index>=0&&s.index<s.questions.length&&(!s.deadline||Number.isFinite(s.deadline))}
if(!validSession(session))session=null;
