function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3000)}
function confirmTask(title,text,callback,label='Confirm'){confirmAction=callback;$('#confirm-title').textContent=title;$('#confirm-text').textContent=text;$('#confirm-ok').textContent=label;$('#confirm-dialog').showModal();$('#confirm-cancel').focus()}
$('#confirm-cancel').onclick=()=>$('#confirm-dialog').close();$('#confirm-ok').onclick=()=>{const cb=confirmAction;$('#confirm-dialog').close();cb?.()};
