const badge=unit=>`<span class="badge ${unit===3?'partial':'verified'}">${unit===3?'Partially verified for Midterm':'Verified midterm'}</span>`;
const scopeNote=()=>`<div class="scope-note"><p>${SCOPE_EN}</p>${ar(SCOPE_AR)}</div>`;
const unitWarning=u=>u===3?`<div class="scope-note"><strong>Partially verified for Midterm</strong><p>The exact final portion needs confirmation. These lessons support preparation; inclusion is not guaranteed.</p>${ar('محتوى الوحدة متاح للتدريب؛ آخر جزء يدخل الميد يحتاج تأكيدًا من المدرّس.')}</div>`:'';
const heading=(eyebrow,title,sub='',extra='')=>`<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${extra}</div>`;
const accuracy=o=>o.total?`${Math.round(o.correct/o.total*100)}%`:'—';
const development=()=>`<div class="development"><p>This version is ready for studying and use now. More improvements and deeper enhancements are coming later, but they take time to build properly.</p>${ar('هذه النسخة الحالية مخصصة للمذاكرة والاستخدام الآن. تحسينات إضافية وتطويرات أعمق قادمة لاحقًا، لكنها تحتاج وقت حتى تُنفذ بشكل صحيح.')}</div>`;
function completeButton(id){return `<button data-action="complete" data-id="${id}" class="${progress.lessons.includes(id)?'':'primary'}">${progress.lessons.includes(id)?'Completed · mark incomplete':'Mark lesson complete / أنهيت الدرس'}</button>`}
function unitCards(){return `<div class="grid">${[1,2,3].map(u=>{const done=LESSONS.filter(l=>l.unit===u&&progress.lessons.includes(l.id)).length;return `<article class="card unit-card"><span class="unit-number">0${u}</span>${badge(u)}<h2>${UNIT_NAMES[u]}</h2><p>${['','Departments, responsibilities and future plans.','Brand identity, connections and advice.','Experience, interviews and better questions.'][u]}</p><div><span class="small muted">${done} / 5 lessons completed</span><div class="progress-track"><span style="width:${done/5*100}%"></span></div></div><a class="button primary" href="#unit/${u}">${done?'Continue unit':'Open unit'}</a></article>`}).join('')}</div>`}
function renderMidterm(){const next=LESSONS.find(l=>l.unit<3&&!progress.lessons.includes(l.id))||LESSONS[0];main.innerHTML=heading('BUS 201 / MIDTERM BETA','Your midterm study desk','Understand the idea. Practise in English. Learn from every answer.')+`<div class="study-banner"><div><h2>Make your next 10 minutes count.</h2><p>Next lesson · ${UNIT_NAMES[next.unit]} / ${next.title}</p></div><a class="button" href="#lesson/${next.id}">Continue studying</a></div>`+scopeNote()+unitCards()+`<section class="section"><div class="section-head"><h2>Practise a skill</h2><span class="small muted">Short sessions. Clear feedback.</span></div><div class="grid"><a class="card tool-link" href="#vocabulary"><h3>Vocabulary Trainer</h3><p>Five modes · ${VOCAB.length} entries across Units 1–3</p></a><a class="card tool-link" href="#grammar"><h3>Grammar Lab</h3><p>Future forms, connectors, indirect questions</p></a><a class="card tool-link" href="#exam"><h3>Exam Practice</h3><p>Quick checks, unit quizzes and a timed session</p></a></div></section><section class="section two"><div class="card"><h3>A useful study rhythm</h3><p>Read one short explanation, answer a few questions, then review your mistakes before moving on.</p>${ar('افهم القاعدة أولًا، ثم خصّص أغلب وقتك للتدريب. لا تكتفِ بقراءة الإجابة الصحيحة؛ افهم لماذا أخطأت.')}<a href="#progress">View your progress</a></div><div class="card"><h3>Midterm at a glance</h3><p><strong>20 questions · 60 minutes</strong></p><p class="muted">Vocabulary, Grammar, Listening, Reading, Writing / Functional Language.</p><a href="#intro">Understand the course & exam</a></div></section>`+development()}
function renderIntro(){main.innerHTML=heading('START HERE','Business English, in context','BUS 201 · Professional Business Speaking')+`<div class="two"><section class="card"><h2>What is BUS 201?</h2><p>Practise English for professional situations: describe your role, meet colleagues, explain a brand and take part in an interview.</p>${ar('هذه مادة لغة أعمال: نتعلم كيف نستخدم الإنجليزية في مواقف العمل، لا كيف نحفظ تعريفات نظرية فقط. المصطلحات والأسئلة بالإنجليزية، والعربي يساعد على فهمها.')}<p>General English covers everyday communication. Business English applies language to workplace purposes, audiences and tasks.</p>${ar('الفرق في السياق والهدف: تقديم نفسك مهنيًا، كتابة رسالة واضحة، سؤال مهذب، أو عرض فكرة لزملائك.')}<p class="source">Course Pack pp.3–5 · Business Partner B1+</p></section><section class="card accent"><h2>Your midterm</h2><div class="row"><div><div class="stat">20</div>questions</div><div><div class="stat">60</div>minutes</div></div><p class="section">The Course Pack lists Vocabulary, Grammar, Listening, Reading and Writing / Functional Language.</p>${ar('توجد تعارضات في النسب المنشورة؛ لذلك لا نعرض نسبًا موحدة أو نزعم أن توزيع التدريب يطابق الاختبار الرسمي.')}<p class="source">Course Pack p.18. The source says specifications may change.</p></section></div><section class="section"><h2>Know what you’re practising</h2><div class="grid">${[
['Vocabulary','Words and expressions used to communicate meaning.','مفردات وتراكيب: مثل report to وbrand image.'],['Grammar','How words are arranged to form accurate sentences.','قواعد بناء الجملة واختيار الصيغة المناسبة.'],['Functional Language','Language chosen for a purpose, such as advice or introductions.','عبارات نختارها حسب الموقف: نصيحة، تعارف، أو طلب توضيح.'],['Reading','Understanding the main idea and finding details in a text.','فهم الفكرة الرئيسية والتفاصيل من النص.'],['Listening','Understanding spoken English and the speaker’s purpose.','فهم الكلام المسموع؛ الصوت الأصلي غير مرفق بهذه النسخة.'],['Pronunciation','Sounds, word stress, rhythm and pauses.','الأصوات والنبر والوقفات التي تجعل الكلام أوضح.']].map(([a,b,c])=>`<div class="card"><h3>${a}</h3><p>${b}</p>${ar(c)}</div>`).join('')}</div></section><section class="section card"><h2>Listening strategy</h2><ol><li>Read the questions and identify the information you need.</li><li>Listen for the main idea first, then the requested details.</li><li>Notice corrections and contrast words; do not choose an answer just because you heard one familiar word.</li></ol>${ar('هذا إرشاد للمذاكرة، وليس اختبار استماع. لا تحتوي النسخة على تسجيلات Pearson أو أصوات بديلة منسوبة إليها. استخدم التسجيلات المرخصة التي يتيحها المقرر.')}<p class="badge">Audio practice not available in this beta</p></section><section class="section card"><h2>MEL before the midterm</h2>${table(['Week','Assigned practice'],[['4','Unit 1 video Activity 1; plural endings Ex1; Workbook 1'],['5','Unit 2 video Activities 1–2; plural endings Ex2; Workbook 2'],['6','Unit 3 video 1A–1B; a/an Ex1; Workbook 3']])}<p>These assignments carry marks in the current Course Pack, even though a source file is named “Optional Pronunciation Practice”.</p>${ar('هذه التدريبات المحلية لا ترسل الواجب إلى MEL ولا تغني عن إكمال التكليف على المنصة.')}<p class="source">Course Pack pp.17–18 · 7.5 MEL marks allocated across these three weeks.</p></section>`+development()}
function renderUnit(u){main.innerHTML=heading(`UNIT 0${u}`,UNIT_NAMES[u],['','Describe what a company does and how people work together.','Explain a brand, connect your ideas and support your colleagues.','Present your experience and understand other people clearly.'][u],badge(u))+unitWarning(u)+`<div class="lesson-list">${LESSONS.filter(l=>l.unit===u).map(l=>`<a class="lesson-link" href="#lesson/${l.id}"><span class="number">${l.number}</span><span><h3>${l.title}</h3><p>${l.subtitle}</p></span><span class="done">${progress.lessons.includes(l.id)?'Completed':'Study'}</span></a>`).join('')}</div><div class="section card row"><div><h3>Ready to use it?</h3><p class="muted">12 original questions · mixed skills · review every answer.</p></div><button class="primary" data-action="unit-quiz" data-unit="${u}">Unit ${u} practice</button></div>`}
function vocabLesson(u){let terms=u===1?['finance','human resources','marketing','operations','production','sales','customer service','quality control','recruitment','supply chain','role','involve','lead','make sure','run','report to','head of','work closely with','look after','take care of','responsible for','in charge of','coordinate with','bureaucratic','centralised','decentralised','hierarchy','innovative']:u===2?['brand','image','client base','bad history','cautious approach','core business','fast growth','further afield','brand stretching','ultra-luxury','venture into','awareness','customer engagement','interactive marketing','logo','loyalty','product placement']:['character','employer','CV / résumé','jobseeker','internship','cliché / clichéd','gain','be of value to','apply for','sort out','come across well','stand out from'];const entries=terms.map(t=>VOCAB.find(v=>v.term===t&&v.unit===u));return `<h2>What is it? · Words in context</h2><p>Learn the meaning together with a useful phrase, then use it in a sentence.</p>${ar('لا تحفظ ترجمة منفردة فقط. احفظ الكلمة مع تركيبها، ثم جرّب تذكرها قبل كشف الجواب.')}${u===1?example('My role involves training new staff. I lead a small team, report to the operations director and work closely with Finance.') : u===2?example('Our brand image is how people see us. Awareness is whether people know us; engagement is their interest and involvement.'):example('The employer hires people. A jobseeker looks for work. An internship helps you gain experience.')}${table(['Term / phrase','Meaning','Example'],entries.map(v=>[`${esc(v.term)}${v.alias?`<br><small>${esc(v.alias)}</small>`:''}`,`${esc(v.definition)}${ar(esc(v.ar))}`,esc(v.example)]))}${u===1?mistake('I am responsible of recruitment.','I am responsible for recruitment.','احفظ responsible for وin charge of وreport to كتراكيب. run هنا يدير، وrunning صيغة ing.'):u===2?`<div class="mistake"><strong>Product placement ≠ manufacturing location</strong>${ar('Product placement هو إظهار المنتج ضمن فيلم أو برنامج للإعلان؛ ليس مكان التصنيع. image ليست awareness أو engagement.')}</div>`:`<div class="mistake"><strong>Employer ≠ employee</strong>${ar('Employer صاحب العمل، وليس الموظف. Come across well يترك انطباعًا جيدًا؛ stand out from يتميز عن غيره، ولا يعنيان المعنى نفسه.')}</div>`}<a class="button primary" href="#vocabulary/${u}">Train Unit ${u} vocabulary</a><p class="source">Audited Vocabulary Map · ${['','S28 p.1; S20 p.1','S29 p.1; S21 p.1; corrected key in S50 p.4','S30 p.1; S24 p.1; Extra Activities Key'][u]}. Definitions, Arabic support and examples are editorial teaching content.</p>`}
function functionalCards(u){return FUNCTIONS.filter(g=>!u||g.unit===u).map(g=>`<article class="card"><div class="row"><span class="eyebrow">UNIT ${g.unit}</span>${g.unit===3?badge(3):''}</div><h3>${g.title}</h3><p>${g.purpose}</p>${ar(g.ar)}<div class="example"><strong>${esc(g.phrase)}</strong></div><p><strong>In context:</strong> ${esc(g.example)}</p><p class="small"><strong>Watch out:</strong> ${esc(g.mistake)}</p><p class="source">${g.source} · Workplace context; no unsupported formality label.</p></article>`).join('')}
function readingLesson(u){const writing=[null,{title:'Organise an email',model:'Subject: Tuesday’s visit\n\nDear Lina,\nI’m writing to confirm your visit on Tuesday. First, we’ll meet in reception at nine. After that, we’ll visit Production. Please let me know if you need directions.\nKind regards,\nSami',task:'Write a short email confirming a visitor’s appointment. Include the date, a simple schedule and a closing.',check:'هل ذكرت هدف الرسالة؟ هل رتبت التفاصيل؟ هل وضعت تحية وختامًا؟',rule:'Opening → purpose → details → closing.'},{title:'Reply to an invitation',model:'Dear Ms Ali,\nThank you for inviting me to the presentation. Unfortunately, I am unable to attend because I have another meeting. I hope the event goes well.\nKind regards,\nSara',task:'Write two replies to an invitation: one accepting and one politely declining.',check:'هل ردك قبول أم رفض واضح؟ هل استخدمت Unfortunately للرفض وليس للقبول؟',rule:'I would be delighted to… accepts. Unfortunately, I am unable to… declines.'},{title:'Introduce a job application',model:'Dear Hiring Manager,\nI am writing to apply for the customer service internship. I have experience helping customers at a university event. I believe my communication skills would be of value to your team. Please find my CV enclosed.\nKind regards,\nRana',task:'Write a short covering letter for an internship. Name the role and give one specific example of a relevant skill.',check:'هل حددت الوظيفة؟ هل أضفت دليلًا على المهارة بدل عبارة عامة؟ هل أشرت للسيرة الذاتية؟',rule:'Role → relevant experience → value to the employer → CV / next step.'}][u];return `<h2>Read for purpose, then detail</h2><p>Read the text once for the main idea. Read again to find evidence for each answer.</p>${ar('ابدأ بالفكرة الرئيسية ثم ابحث عن دليل للإجابة. لا تستخدم معرفتك الخارجية لإكمال شيء لم يذكره النص.')}<h3>${READINGS[u].title}</h3><div class="passage">${READINGS[u].text}</div><p class="source">${READINGS[u].source}. This text is original and fictional.</p><button class="primary" data-action="lesson-quiz" data-unit="${u}" data-category="Reading">Reading check · 4 questions</button><h2 class="section">${writing.title}</h2><p>${writing.rule}</p><div class="example" style="white-space:pre-line">${writing.model}</div><h3>Your turn</h3><p>${writing.task}</p>${ar(writing.check)}<p class="small muted">Self-check: write on paper or in your notes. Free writing is not automatically graded.</p><button data-action="lesson-quiz" data-unit="${u}" data-category="Writing">Writing check · 3 questions</button><p class="source">Original model based on Unit ${u} Extra Activities p.5 and Workbook p.5.</p>`}
function pronunciationLesson(u){return [null,`<h2>Plural endings: listen to the last sound</h2><p>The spelling -s does not always represent the same sound.</p>${ar('نهاية الجمع تعتمد على آخر صوت في المفرد، لا على اسم الحرف فقط. هذا شرح كتابي؛ لا يوجد تسجيل صوتي في النسخة الحالية.')}${table(['Ending','After','Examples'],[['/s/','Voiceless sounds such as /p/, /t/, /k/ (except the sibilant group below)','shops, products, desks'],['/z/','Vowels and voiced sounds (except the sibilant group below)','teams, jobs, managers'],['/ɪz/','/s/, /z/, /ʃ/, /ʒ/, /tʃ/, /dʒ/','buses, watches, changes']])}<p>Do not add an extra syllable to every plural. <strong>Desks</strong> stays one syllable; <strong>watches</strong> has an extra syllable.</p>${ar('تدريب word stress موجود أيضًا في U1: انتبه للمقطع المنبور داخل الكلمة عند استخدام تسجيل المقرر. لا تحاول استنتاج النبر من التهجئة وحدها.')}<p class="source">Optional Pronunciation Practice pp.1–4; Homework 1 p.6. Assigned in Week 4.</p>`,
`<h2>The extra syllable: /ɪz/</h2><p>After a sibilant ending, the plural adds a separate syllable: <strong>watches, buses, changes</strong>.</p>${ar('بعد الأصوات الصفيرية المحددة في الجدول، نضيف مقطعًا صوتيًا /ɪz/. كلمة watches ليست watchs بلا مقطع إضافي.')}${example('watch → watches /ɪz/<br>brand → brands /z/<br>shop → shops /s/')}<h3>Pauses make meaning easier to follow</h3>${example('Next month, | we are introducing a new brand.<br>First of all, | let me explain our campaign.')}<p>The line marks a useful pause, not a word to pronounce. Keep meaning groups together. Compound-phrase stress is also practised in the Unit 2 workbook; follow the course recording for the model.</p>${ar('الوقفة تساعد المستمع على متابعة الفكرة. لا تفصل أداة التعريف عن الاسم أو الفعل المساعد عن الفعل دون سبب. النبر يحتاج نموذج المقرر الصوتي.')}<p class="source">Optional Pronunciation Practice pp.5–7; Homework 2 p.6. Assigned in Week 5.</p>`,
`<h2>a / an: choose by sound</h2><p>Use <strong>a</strong> before a consonant sound and <strong>an</strong> before a vowel sound.</p>${ar('المعيار هو أول صوت مسموع، وليس أول حرف مكتوب. university تبدأ بصوت /j/ مثل you، لذلك a university؛ أما employer فتبدأ بصوت متحرك، لذلك an employer.')}${example('a jobseeker · an employer<br>a university · an internship')}<h3>Sentence stress</h3><p>Stress can highlight the information you need. In “When does the <strong>INTERVIEW</strong> start?”, the emphasis draws attention to the interview. Practise with the course audio rather than treating capitals as a recording.</p>${ar('النبر يبرز كلمة مهمة بحسب المعنى. توجد أيضًا تمارين word-family stress في الوحدة؛ لا تحتوي هذه النسخة على صوت لتقييم نطقك.')}<p class="source">Optional Pronunciation Practice pp.8–9; Workbook 3 p.6. a/an is assigned in Week 6; the full U3 exam boundary remains uncertain.</p>`][u]+`<div class="scope-note">Written pronunciation guidance only. Listening and pronunciation cannot be fully assessed here without audio.</div>`}
function renderLesson(id){const l=LESSONS.find(l=>l.id===id);if(!l)return renderNotFound();let body='';if(l.type==='vocab')body=vocabLesson(l.unit);if(l.type==='grammar'){const g=GRAMMAR[l.unit];body=`<h2>What is it?</h2><p>${g.what}</p><h3>Why use it?</h3><p>${g.why}</p>${g.body()}<p class="source">${g.source}</p>`}if(l.type==='functional')body=`<h2>Choose language for the situation</h2><p>Identify what the speaker wants to do, then choose a suitable phrase.</p>${ar('اسأل نفسك: هل أريد التعارف، تقديم نصيحة، أم طلب توضيح؟ العبارة الصحيحة نحويًا قد لا تناسب الموقف.')}<div class="lesson-list">${functionalCards(l.unit)}</div>`;if(l.type==='reading')body=readingLesson(l.unit);if(l.type==='pronunciation')body=pronunciationLesson(l.unit);main.innerHTML=`<div class="lesson-body"><a href="#unit/${l.unit}">Unit ${l.unit} · ${UNIT_NAMES[l.unit]}</a><div class="section">${heading(`LESSON ${l.unit}.${l.number}`,l.title,l.subtitle,badge(l.unit))}</div>${unitWarning(l.unit)}<article class="card">${body}</article><section class="card"><h2>Practise before you move on</h2><p>Try a short check, review the explanation, then practise in a mixed unit quiz.</p><div class="actions"><button class="primary" data-action="lesson-quiz" data-unit="${l.unit}" data-category="${l.category}">Quick Check</button><button data-action="unit-quiz" data-unit="${l.unit}">Exam-style unit practice</button></div></section><div class="actions">${completeButton(l.id)}<a class="button" href="#unit/${l.unit}">Back to unit</a></div></div>`}
function renderGrammar(){main.innerHTML=heading('PRACTICE LAB','Grammar, with a reason','Learn the pattern. Choose the form. Explain your answer.')+`<div class="grid">${[1,2,3].map(u=>`<article class="card"><p class="eyebrow">UNIT ${u}</p>${badge(u)}<h2 class="section">${GRAMMAR[u].title}</h2><p>${GRAMMAR[u].what}</p><div class="actions"><a class="button" href="#lesson/${u}-grammar">Study the rule</a><button class="primary" data-action="lesson-quiz" data-unit="${u}" data-category="Grammar">Practise</button></div></article>`).join('')}</div><div class="section card"><h3>Start with meaning</h3><p>For future forms, ask what kind of plan it is. For connectors, ask how the ideas relate. For indirect questions, find the subject and put it before the verb.</p>${ar('هذه هي محاور القواعد الثلاثة لهذه النسخة. الأسئلة غير المباشرة من U3 ونطاق دخولها التفصيلي يحتاج تأكيدًا.')}</div>`}
function renderFunctional(u=1){main.innerHTML=heading('SITUATION PRACTICE','Say the right thing','Useful phrases, clear purposes and original examples.')+`<div class="pill-tabs">${[1,2,3].map(n=>`<a class="${u===n?'selected':''}" href="#functional/${n}">Unit ${n} · ${UNIT_NAMES[n]}</a>`).join('')}</div>`+unitWarning(u)+`<div class="two">${functionalCards(u)}</div><div class="section actions"><button class="primary" data-action="lesson-quiz" data-unit="${u}" data-category="Functional Language">Practise these situations</button></div>`}
function renderVocab(unit){if(unit&&['1','2','3'].includes(unit))vocabSettings.unit=unit;main.innerHTML=heading('RECALL / RECOGNISE / USE','Vocabulary Trainer','One word at a time. Try an answer before you check it.')+`<div class="controls"><label class="field">Unit<select id="v-unit">${[1,2,3].map(u=>`<option value="${u}" ${vocabSettings.unit===String(u)?'selected':''}>${u} · ${UNIT_NAMES[u]}${u===3?' (partial)':''}</option>`).join('')}</select></label><label class="field">Practice mode<select id="v-mode">${[['en-ar','English → Arabic'],['ar-en','Arabic → English'],['definition','Definition → term'],['fill','Fill in the blank'],['mcq','Multiple choice']].map(([id,t])=>`<option value="${id}" ${vocabSettings.mode===id?'selected':''}>${t}</option>`).join('')}</select></label><span class="small muted">Accuracy: <strong id="v-accuracy">${accuracy(progress.vocabulary)}</strong></span></div><div id="v-scope">${unitWarning(Number(vocabSettings.unit))}</div><div class="trainer" id="v-card"></div>`;$('#v-unit').onchange=e=>{vocabSettings.unit=e.target.value;vocabQueue=[];$('#v-scope').innerHTML=unitWarning(Number(vocabSettings.unit));nextVocab()};$('#v-mode').onchange=e=>{vocabSettings.mode=e.target.value;vocabQueue=[];nextVocab()};nextVocab()}
function fillData(v){const candidates=[v.term.split(' / ')[0].replace(/ \(.+\)$/,''),v.alias,v.term==='come across well'?'came across well':null,v.term==='gain'?'gain':null].filter(Boolean);for(const term of candidates){const at=v.example.toLowerCase().indexOf(term.toLowerCase());if(at>=0)return {prompt:v.example.slice(0,at)+'______'+v.example.slice(at+term.length),answer:v.example.slice(at,at+term.length)}}return null}
function nextVocab(){let pool=VOCAB.filter(v=>v.unit===Number(vocabSettings.unit));if(vocabSettings.mode==='fill')pool=pool.filter(fillData);if(!vocabQueue.length){vocabQueue=shuffle(pool);if(vocabQueue.length>1&&vocabQueue[0].id===lastWord)[vocabQueue[0],vocabQueue[1]]=[vocabQueue[1],vocabQueue[0]]}currentWord=vocabQueue.shift();lastWord=currentWord.id;vocabAnswered=false;const v=currentWord,mode=vocabSettings.mode;const prompt=mode==='en-ar'?v.term:mode==='ar-en'?v.ar:mode==='fill'?fillData(v).prompt:v.definition;let answers='';if(mode==='en-ar'||mode==='mcq'){const key=mode==='en-ar'?'ar':'term',correct=v[key];const others=shuffle(VOCAB.filter(x=>x.unit===v.unit&&x.id!==v.id&&x[key]!==correct));const values=[...new Set(others.map(x=>x[key]))].slice(0,3);answers=`<div class="options">${shuffle([correct,...values]).map((x,i)=>`<button class="option" data-v-answer="${esc(x)}"><span class="letter">${String.fromCharCode(65+i)}</span><span ${mode==='en-ar'?'lang="ar" dir="rtl"':''}>${esc(x)}</span></button>`).join('')}</div>`}else answers=`<form id="v-form"><label class="field">Your English answer<input id="v-answer" type="text" autocomplete="off" spellcheck="false" placeholder="Type the word or phrase" required></label><button class="primary section" type="submit">Check answer</button></form>`;$('#v-card').innerHTML=`<section class="card trainer-card"><div class="row"><span class="eyebrow">UNIT ${v.unit} · ${pool.length} ENTRIES IN THIS MODE</span>${badge(v.unit)}</div><p class="trainer-prompt ${mode==='ar-en'?'ar':''}" ${mode==='ar-en'?'lang="ar"':''}>${esc(prompt)}</p>${mode==='fill'?`<p class="small muted">Clue: ${esc(v.definition)}</p>`:''}${answers}<div id="v-feedback" aria-live="polite"></div><div class="actions section"><button data-action="v-skip">Skip</button><button data-action="v-reveal">Show answer</button></div></section>`;document.querySelectorAll('[data-v-answer]').forEach(b=>b.onclick=()=>answerVocab(b.dataset.vAnswer));if($('#v-form'))$('#v-form').onsubmit=e=>{e.preventDefault();answerVocab($('#v-answer').value)}}
function normalize(s){return String(s??'').normalize('NFKC').toLowerCase().replace(/[’‘]/g,"'").replace(/[.,!?;:]/g,'').replace(/\s+/g,' ').trim()}
function vocabAnswers(v){const a=[v.term,...v.term.split(' / '),v.alias].filter(Boolean);if(v.term==='CV / résumé')a.push('resume','résumé','cv');if(v.term==='cliché / clichéd')a.push('cliche','cliched');return a}
function answerVocab(value,reveal=false){if(vocabAnswered)return;vocabAnswered=true;const v=currentWord,mode=vocabSettings.mode;const expected=mode==='en-ar'?[v.ar]:mode==='fill'?[fillData(v).answer]:vocabAnswers(v);const correct=!reveal&&expected.some(x=>normalize(x)===normalize(value));progress.vocabulary.total++;if(correct)progress.vocabulary.correct++;saveProgress();$('#v-accuracy').textContent=accuracy(progress.vocabulary);document.querySelectorAll('[data-v-answer]').forEach(b=>{b.disabled=true;if(normalize(b.dataset.vAnswer)===normalize(expected[0]))b.classList.add('correct');else if(b.dataset.vAnswer===value)b.classList.add('incorrect')});if($('#v-form'))$('#v-form').querySelectorAll('input,button').forEach(x=>x.disabled=true);$('#v-feedback').innerHTML=`<div class="feedback ${correct?'':'incorrect'}"><strong>${correct?'Correct.':reveal?'Answer revealed · counted as a review attempt':'Not quite. Review the meaning.'}</strong><h3 class="section">${esc(v.term)}${v.alias?` <small>(${esc(v.alias)})</small>`:''}</h3>${ar(esc(v.ar))}<p>${esc(v.definition)}</p><p><strong>Phrase:</strong> ${esc(v.collocation)}<br><strong>Example:</strong> ${esc(v.example)}</p>${mode==='fill'?`<p><strong>Blank:</strong> ${esc(fillData(v).answer)}</p>`:''}<details><summary>Content reference</summary><p class="source">${esc(v.source)} · ${esc(v.confidence)} content confidence. Unit ${v.unit}${v.unit===3?' scope remains partial.':'.'}</p></details></div><button class="primary section" data-action="v-next">Next word</button>`;$('#v-card [data-action="v-skip"]').disabled=true;$('#v-card [data-action="v-reveal"]').disabled=true;$('#v-feedback [data-action="v-next"]').focus()}
function makeQuestions(list){return shuffle(list).map(q=>({...q,choices:q.choices?shuffle(q.choices):null,matchOptions:q.matchOptions?shuffle(q.matchOptions):null}))}
function startQuiz(mode,unit=1,category=null){const launch=()=>{let list,title;if(mode==='simulation'){const include=$('#include-u3')?.checked||false;const pool=BANK.filter(q=>include||q.unit<3);list=[];for(const [cat,count] of [['Vocabulary',6],['Grammar',5],['Reading',5],['Functional Language',2],['Writing',2]])list.push(...shuffle(pool.filter(q=>q.category===cat)).slice(0,count));title=include?'Midterm training · Units 1–3 (U3 partial)':'Midterm training · Units 1–2'}else if(mode==='quick'){list=shuffle(BANK.filter(q=>q.unit<3&&q.category!=='Pronunciation')).slice(0,5);title='Quick Practice · Units 1–2'}else if(mode==='unit'){const pool=BANK.filter(q=>q.unit===unit);list=[];for(const [cat,n] of [['Vocabulary',3],['Grammar',3],['Functional Language',2],['Reading',2],['Writing',1],['Pronunciation',1]])list.push(...shuffle(pool.filter(q=>q.category===cat)).slice(0,n));title=`Unit ${unit} Practice`}else{const pool=BANK.filter(q=>q.unit===unit&&q.category===category);list=shuffle(pool).slice(0,category==='Reading'?4:5);title=`Unit ${unit} · ${category} Check`}
session={id:Date.now().toString(36)+Math.random().toString(36).slice(2,7),mode,title,questions:makeQuestions(list),index:0,answers:{},deadline:mode==='simulation'?Date.now()+60*60*1000:null,submitted:false,started:Date.now()};saveSession();go('quiz')};if(session&&!session.submitted)confirmTask('Start a new practice?','Your current unfinished session will be replaced. سيتم استبدال التدريب الحالي دون احتساب نتيجته.',launch,'Start new');else launch()}
function renderExam(){main.innerHTML=heading('APPLY WHAT YOU KNOW','Exam Practice','Original questions. Useful feedback. A clear view of what to improve.')+scopeNote()+`${session?`<div class="study-banner"><div><h3>${esc(session.title)}</h3><p>${session.submitted?'Your answer review is ready.':`${Object.keys(session.answers).length} of ${session.questions.length} answered · your timer continues if you leave a timed session.`}</p></div><a href="#quiz" class="button">${session.submitted?'Review answers':'Resume session'}</a></div>`:''}<div class="grid"><article class="card"><p class="eyebrow">A SHORT WARM-UP</p><h2>Quick Practice</h2><p>5 questions from Units 1–2. No timer.</p><button class="primary" data-action="quick-quiz">Start 5 questions</button></article><article class="card"><p class="eyebrow">ONE UNIT AT A TIME</p><h2>Unit Practice</h2><p>12 questions mixing vocabulary, grammar and communication.</p><label class="field">Choose unit<select id="exam-unit">${[1,2,3].map(u=>`<option value="${u}">Unit ${u}${u===3?' · partial scope':''}</option>`).join('')}</select></label><button class="primary section" data-action="selected-unit-quiz">Start unit practice</button></article><article class="card accent"><p class="eyebrow">TIMED TRAINING</p><h2>Midterm Simulation</h2><p><strong>20 questions · 60 minutes</strong></p><label class="check-label"><input id="include-u3" type="checkbox">Include Unit 3 (partial scope)</label><button class="primary section" data-action="simulation">Start timed practice</button></article></div><section class="section card"><h2>What this simulation covers</h2><p>The course exam is 20 questions in 60 minutes. This beta uses an <strong>editorial practice mix</strong>: 6 Vocabulary, 5 Grammar, 5 Reading, 2 Functional Language and 2 Writing questions. This is not an official exam blueprint.</p>${ar('هذه محاكاة للوقت والتدريب، وليست توقعًا لتوزيع الاختبار. المصدر يتضمن الاستماع، لكن الصوت غير متاح هنا؛ لذا لا تحصل على تقييم لمهارة الاستماع. توزيعنا تعليمي ومعلن، ولا يعالج تعارض نسب المصدر باختراع نسب رسمية.')}<p>Each numbered item is worth one point. Matching items require all pairs to be correct; there is no partial credit. Unanswered items receive zero. You can move back and forth before submission.</p>${ar('الأسئلة اختيار متعدد، إكمال، أو مطابقة. مطابقة الأزواج كلها تُحسب سؤالًا واحدًا. التفسيرات تظهر بعد التسليم.')}<p class="source">Course Pack p.18; Exam Pattern Audit. ${BANK.length} original question items in the local bank.</p></section><section class="section card"><h3>Listening strategy · not a scored section</h3><p>Read the task before listening. Identify names, times and reasons. Listen for corrections and contrasts, then check your answer against what was actually said.</p>${ar('استخدم صوت المقرر من مصدره المرخص. لا يوجد تسجيل أو TTS بديل منسوب إلى Pearson في هذه النسخة.')}</section>`}
function go(route){if(location.hash.slice(1)===route)render();else location.hash=route}
function questionAnswered(q){const a=session.answers[q.id];if(q.type==='match')return a&&q.pairs.every(([id])=>!!a[id]);return typeof a==='string'&&a.trim().length>0}
function correctQuestion(q,a){if(q.type==='match')return !!a&&q.pairs.every(([id])=>a[id]===q.answer[id]);return (Array.isArray(q.answer)?q.answer:[q.answer]).some(x=>normalize(a)===normalize(x))}
function answerLabel(q,a){if(q.type==='match')return q.pairs.map(([id,label])=>`${label} → ${a?.[id]||'—'}`).join('\n');return a||'Not answered'}
function expectedLabel(q){if(q.type==='match')return answerLabel(q,q.answer);return (Array.isArray(q.answer)?q.answer:[q.answer]).join(' / ')}
function quizNav(){return `<div class="question-nav" aria-label="Question navigation">${session.questions.map((q,i)=>`<button data-action="q-go" data-index="${i}" class="${i===session.index?'current':questionAnswered(q)?'answered':''}" aria-label="Question ${i+1}${questionAnswered(q)?', answered':''}" ${i===session.index?'aria-current="step"':''}>${i+1}</button>`).join('')}</div>`}
function renderQuiz(){if(!session){go('exam');return}if(session.submitted){renderResults();return}if(session.deadline&&Date.now()>=session.deadline){submitQuiz(true);return}const q=session.questions[session.index],a=session.answers[q.id];main.innerHTML=heading('PRACTICE IN PROGRESS',esc(session.title),'Answers are saved as you go.',session.deadline?'<div class="timer" id="timer" role="timer" aria-label="Time remaining"></div>':'<span class="badge">Untimed practice</span>')+`${session.questions.some(x=>x.unit===3)?unitWarning(3):''}<div class="row"><span id="answered-count" class="small muted">${session.questions.filter(questionAnswered).length} / ${session.questions.length} answered</span><a href="#exam">Back to practice menu</a></div><div id="question-nav">${quizNav()}</div><article class="card" id="question-card"><div class="row"><p class="eyebrow">QUESTION ${session.index+1} OF ${session.questions.length} · UNIT ${q.unit}</p><span class="badge">${q.category}</span></div>${q.passage?`<div class="passage"><strong>${READINGS[q.passage].title}</strong><p>${READINGS[q.passage].text}</p><small>Original practice text</small></div>`:''}<h2 class="question-prompt" id="q-prompt">${esc(q.prompt)}</h2>${q.type==='mcq'?`<div class="options" role="group" aria-labelledby="q-prompt">${q.choices.map((c,i)=>`<button class="option ${a===c?'selected':''}" data-answer="${esc(c)}" aria-pressed="${a===c}"><span class="letter">${String.fromCharCode(65+i)}</span><span>${esc(c)}</span></button>`).join('')}</div>`:q.type==='match'?`<div>${q.pairs.map(([id,text])=>`<label class="match-row"><span>${esc(text)}</span><select data-match="${id}" aria-label="Match ${esc(text)}"><option value="">Choose…</option>${q.matchOptions.map(o=>`<option ${a?.[id]===o?'selected':''} value="${esc(o)}">${esc(o)}</option>`).join('')}</select></label>`).join('')}</div>`:`<label class="field">Your answer<input type="text" id="q-text" value="${esc(a||'')}" autocomplete="off" spellcheck="false" placeholder="Type your answer in English"></label><p class="small muted">Capitalisation, extra spaces and final punctuation are ignored.</p>`}<div class="actions section"><button data-action="q-prev" ${session.index===0?'disabled':''}>Previous</button><button class="primary" data-action="q-next" ${session.index===session.questions.length-1?'disabled':''}>Next question</button><button data-action="q-submit">Submit answers</button></div></article>`;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{session.answers[q.id]=b.dataset.answer;saveSession();document.querySelectorAll('[data-answer]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)});updateAnswerNav()});document.querySelectorAll('[data-match]').forEach(s=>s.onchange=()=>{session.answers[q.id]={...(session.answers[q.id]||{}),[s.dataset.match]:s.value};saveSession();updateAnswerNav()});if($('#q-text'))$('#q-text').oninput=e=>{session.answers[q.id]=e.target.value;saveSession();updateAnswerNav()};updateTimer()}
function updateAnswerNav(){if($('#answered-count'))$('#answered-count').textContent=`${session.questions.filter(questionAnswered).length} / ${session.questions.length} answered`;if($('#question-nav'))$('#question-nav').innerHTML=quizNav()}
function updateTimer(){if(!session||session.submitted||!session.deadline)return;const left=Math.max(0,Math.ceil((session.deadline-Date.now())/1000));if($('#timer')){$('#timer').textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;$('#timer').classList.toggle('urgent',left<300)}if(left===0)submitQuiz(true)}
function submitQuiz(expired=false){if(!session||session.submitted)return;session.submitted=true;session.expired=expired;session.score=session.questions.filter(q=>correctQuestion(q,session.answers[q.id])).length;session.finished=Date.now();if(!progress.quizzes.some(r=>r.id===session.id)){for(const q of session.questions){const key=q.category==='Grammar'?'grammar':q.category==='Vocabulary'?'vocabulary':null;if(key){progress[key].total++;if(correctQuestion(q,session.answers[q.id]))progress[key].correct++}}progress.quizzes.push({id:session.id,title:session.title,score:session.score,total:session.questions.length,date:session.finished,mode:session.mode});if(session.mode==='simulation')progress.best=Math.max(progress.best??0,session.score);saveProgress()}saveSession();if($('#confirm-dialog').open)$('#confirm-dialog').close();if(location.hash==='#quiz')renderResults();else toast('Timed session submitted. Review it in Exam Practice.')}
function renderResults(){main.innerHTML=heading('ANSWER REVIEW',esc(session.title),'Use the explanations to decide what to study next.')+`<section class="card"><div class="row"><div><div class="results-score">${session.score}<span class="muted" style="font-size:1.5rem"> / ${session.questions.length}</span></div><p>${Math.round(session.score/session.questions.length*100)}% correct${session.expired?' · Time expired; session submitted automatically.':''}</p></div><div class="actions"><a class="button primary" href="#exam">Choose another practice</a><a class="button" href="#progress">View progress</a></div></div>${session.mode==='simulation'?'<p class="small muted">This score covers written practice only. It does not assess listening or predict an official grade.</p>':''}</section><section class="section"><h2>Review every answer</h2>${session.questions.map((q,i)=>{const ok=correctQuestion(q,session.answers[q.id]);return `<article class="card review-item"><div class="row"><span class="badge ${ok?'verified':'partial'}">${ok?'Correct':'Review'} · Question ${i+1}</span><span class="small muted">Unit ${q.unit} · ${q.category}</span></div><h3 class="section">${esc(q.prompt)}</h3>${q.passage?`<details><summary>Read the text again</summary><p>${READINGS[q.passage].text}</p></details>`:''}<p style="white-space:pre-line"><strong>Your answer:</strong> ${esc(answerLabel(q,session.answers[q.id]))}</p><p class="good" style="white-space:pre-line"><strong>Correct answer:</strong> ${esc(expectedLabel(q))}</p><div class="feedback"><strong>Why?</strong><p dir="auto">${esc(q.explanation)}</p>${ar(esc(q.explanationAr))}</div><p class="source">${esc(q.source)} · Original practice item</p></article>`}).join('')}</section>`;window.scrollTo(0,0)}
function renderProgress(){main.innerHTML=heading('YOUR LEARNING RECORD','Progress','Saved on this browser and device. No account needed.')+`${!storageAvailable?'<div class="scope-note">Browser storage is unavailable. Progress will last only for this visit.</div>':''}<div class="stats">${[[`${progress.lessons.length} / ${LESSONS.length}`,'Lessons completed'],[accuracy(progress.vocabulary),'Vocabulary accuracy'],[accuracy(progress.grammar),'Grammar accuracy'],[progress.best===null?'—':`${progress.best} / 20`,'Best timed score']].map(([a,b])=>`<div class="card"><div class="stat">${a}</div><span class="small muted">${b}</span></div>`).join('')}</div><p class="small muted section">Vocabulary: ${progress.vocabulary.correct}/${progress.vocabulary.total} attempts · Grammar: ${progress.grammar.correct}/${progress.grammar.total} attempts · ${progress.quizzes.length} quizzes completed. Revealing a vocabulary answer counts as a review attempt; skipping does not.</p><section class="section"><h2>By unit</h2>${unitCards()}</section><section class="section card"><h2>Recent quizzes</h2>${progress.quizzes.length?table(['Practice','Result','Date'],progress.quizzes.slice(-10).reverse().map(r=>[esc(r.title),`${r.score} / ${r.total}`,new Date(r.date).toLocaleDateString('en-GB')])):'<p class="muted">Your completed quizzes will appear here. Start with five questions.</p>'}<a href="#exam">Open Exam Practice</a></section><section class="section card"><h3>Reset progress</h3><p>Clear lesson completion, accuracy, quiz history and any active session on this browser. This cannot be undone.</p>${ar('سيُحذف تقدمك المحفوظ لهذه النسخة فقط على هذا المتصفح.')}<button data-action="reset-progress">Reset all progress</button></section>`}
function renderNotFound(){main.innerHTML=heading('PAGE NOT FOUND','Let’s get back to studying.')+'<a class="button primary" href="#midterm">Open Midterm Prep</a>'}
function render(){const [route,id]=location.hash.slice(1).split('/');document.querySelectorAll('#nav a').forEach(a=>{const active=a.hash==='#'+(route==='lesson'?'unit/'+String(id).split('-')[0]:route==='quiz'?'exam':route==='unit'?'unit/'+id:route||'midterm');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');if(!route||route==='midterm')renderMidterm();else if(route==='intro')renderIntro();else if(route==='unit'&&[1,2,3].includes(Number(id)))renderUnit(Number(id));else if(route==='lesson')renderLesson(id);else if(route==='grammar')renderGrammar();else if(route==='vocabulary')renderVocab(id);else if(route==='functional')renderFunctional([1,2,3].includes(Number(id))?Number(id):1);else if(route==='exam')renderExam();else if(route==='quiz')renderQuiz();else if(route==='progress')renderProgress();else renderNotFound();document.title=`BUS 201 · ${$('#main h1')?.textContent||'Midterm Beta'}`;window.scrollTo(0,0)}
main.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const u=Number(b.dataset.unit),action=b.dataset.action;if(action==='complete'){const id=b.dataset.id;progress.lessons=progress.lessons.includes(id)?progress.lessons.filter(x=>x!==id):[...progress.lessons,id];saveProgress();const y=window.scrollY;renderLesson(id);window.scrollTo(0,y);toast(progress.lessons.includes(id)?'Lesson completed / تم إكمال الدرس':'Lesson marked incomplete')}
else if(action==='v-next'||action==='v-skip')nextVocab();else if(action==='v-reveal')answerVocab('',true);else if(action==='quick-quiz')startQuiz('quick');else if(action==='unit-quiz')startQuiz('unit',u);else if(action==='selected-unit-quiz')startQuiz('unit',Number($('#exam-unit').value));else if(action==='lesson-quiz')startQuiz('lesson',u,b.dataset.category);else if(action==='simulation')startQuiz('simulation');else if(action==='q-go'||action==='q-prev'||action==='q-next'){session.index=action==='q-go'?Number(b.dataset.index):session.index+(action==='q-next'?1:-1);saveSession();renderQuiz();$('#q-prompt').setAttribute('tabindex','-1');$('#q-prompt').focus()}
else if(action==='q-submit'){const left=session.questions.filter(q=>!questionAnswered(q)).length;confirmTask('Submit this practice?',`${left?`${left} unanswered question(s) will receive zero. `:''}You can review answers after submitting. يمكنك مراجعة الإجابات بعد التسليم.`,()=>submitQuiz(),'Submit answers')}
else if(action==='reset-progress')confirmTask('Reset all progress?','This clears only BUS 201 data on this browser. لا يمكن التراجع عن حذف التقدم.',()=>{progress=fresh();session=null;saveProgress();saveSession();renderProgress();toast('Progress reset / تم مسح التقدم')},'Reset progress')});
window.addEventListener('hashchange',()=>{render();main.focus({preventScroll:true})});
setInterval(updateTimer,1000);
render();
// Optional browser-native read-only integration; no network or persistence outside this app.
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_bus201_progress',description:'Read local BUS 201 lesson and practice progress without changing it.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Expected an empty object');return {completedLessons:progress.lessons.length,totalLessons:LESSONS.length,vocabularyAccuracy:accuracy(progress.vocabulary),grammarAccuracy:accuracy(progress.grammar),quizzesCompleted:progress.quizzes.length,bestTimedScore:progress.best}}})).catch(()=>{})}catch{}}
